  $j$[]$j$::jsonb,
  $j$[["disobedience", "/ˌdɪsəˈbiːdiəns/", "sự bất tuân"], ["civil disobedience", "/ˈsɪvl ˌdɪsəˈbiːdiəns/", "bất tuân dân sự"], ["just", "/dʒʌst/", "công bằng, chính đáng"], ["injustice", "/ɪnˈdʒʌstɪs/", "sự bất công"], ["well-disposed", "/ˌwel dɪˈspəʊzd/", "tử tế, có thiện chí"], ["undue", "/ˌʌnˈdjuː/", "quá mức"], ["against their will", "/əˈɡenst ðeə wɪl/", "trái với ý muốn"], ["conscience", "/ˈkɒnʃəns/", "lương tâm"], ["damnable", "/ˈdæmnəbl/", "đáng nguyền rủa"], ["unscrupulous", "/ʌnˈskruːpjələs/", "vô lương tâm, bất chấp"], ["the state", "/ðə steɪt/", "nhà nước"], ["standing army", "/ˈstændɪŋ ˈɑːmi/", "quân đội thường trực"], ["judgment", "/ˈdʒʌdʒmənt/", "óc phán đoán"], ["moral", "/ˈmɒrəl/", "đạo đức"], ["abominable", "/əˈbɒmɪnəbl/", "kinh khủng, ghê tởm"], ["obedience", "/əˈbiːdiəns/", "sự vâng lời, phục tùng"], ["moan", "/məʊn/", "than vãn, rên rỉ"], ["shift responsibility", "/ʃɪft rɪˌspɒnsəˈbɪləti/", "đẩy trách nhiệm"], ["solely", "/ˈsəʊlli/", "chỉ, duy nhất"], ["carry out orders", "/ˈkæri aʊt ˈɔːdəz/", "thi hành mệnh lệnh"], ["abandon", "/əˈbændən/", "từ bỏ"], ["dutifully", "/ˈdjuːtɪfəli/", "ngoan ngoãn, tận tụy"], ["pull the trigger", "/pʊl ðə ˈtrɪɡə/", "bóp cò"], ["torture", "/ˈtɔːtʃə/", "tra tấn"], ["discharge", "/dɪsˈtʃɑːdʒ/", "giải ngũ, sa thải"], ["rebel", "/ˈrebl/", "người nổi loạn"], ["condemn", "/kənˈdem/", "lên án"], ["unpatriotic", "/ˌʌnpætriˈɒtɪk/", "không yêu nước"], ["vilify", "/ˈvɪlɪfaɪ/", "bôi nhọ, phỉ báng"], ["radical", "/ˈrædɪkl/", "người cực đoan, cấp tiến"], ["resist", "/rɪˈzɪst/", "chống lại"], ["scum", "/skʌm/", "cặn bã"], ["practical", "/ˈpræktɪkl/", "thực tế"]]$j$::jsonb,
  $j$[["the agents of injustice", "công cụ của sự bất công"], ["an undue respect for law", "sự tôn trọng luật quá mức"], ["against their wills", "trái với ý muốn của họ"], ["against their common sense and consciences", "trái với lẽ thường và lương tâm"], ["at the service of some unscrupulous man in power", "phục vụ một kẻ cầm quyền vô lương tâm"], ["not as men mainly, but as machines", "chủ yếu không phải như con người, mà như cỗ máy"], ["command no more respect than", "không đáng được tôn trọng hơn"], ["are commonly considered good citizens", "thường được coi là công dân tốt"], ["the result of obedience", "kết quả của sự phục tùng"], ["we cry and moan and blame our leaders", "chúng ta than khóc, rên rỉ và đổ lỗi cho lãnh đạo"], ["We shift responsibility to them.", "Chúng ta đẩy trách nhiệm cho họ."], ["Are they solely responsible?", "Chỉ mình họ chịu trách nhiệm sao?"], ["carrying out their orders", "thi hành mệnh lệnh của họ"], ["have abandoned their conscience", "đã từ bỏ lương tâm"], ["dutifully obeying their master", "ngoan ngoãn vâng lời chủ"], ["pulling the trigger", "bóp cò"], ["put in prison for refusing an order", "bị bỏ tù vì từ chối mệnh lệnh"], ["follow their conscience", "làm theo lương tâm"], ["history is usually kind to such people", "lịch sử thường tử tế với những người như vậy"], ["was vilified as a radical", "bị bôi nhọ là kẻ cực đoan"], ["is celebrated as a hero", "được tôn vinh là anh hùng"], ["as important today as it was during their lifetime", "ngày nay vẫn quan trọng như khi họ còn sống"]]$j$::jsonb,
  $j$[["S + never made + someone + adj-er", "Money never made him happier.", "Tiền chưa bao giờ làm anh ấy hạnh phúc hơn.", "never made"], ["A common result of + noun + is that + clause", "A common result of stress is that you can't sleep.", "Một hệ quả phổ biến của căng thẳng là bạn không ngủ được.", "result of"], ["... against + one's + will", "She married him against her will.", "Cô ấy lấy anh ta trái với ý muốn của mình.", "against"], ["S + have no doubt that + clause", "I have no doubt that you will pass.", "Tôi không nghi ngờ gì là bạn sẽ đỗ.", "no doubt"], ["... not as A, but as B", "He treats us not as workers, but as friends.", "Anh ấy đối xử với chúng tôi không như nhân viên, mà như bạn bè.", "not as|but as"], ["S + be + commonly considered + noun/adj", "Rice is commonly considered a healthy food.", "Gạo thường được coi là thực phẩm lành mạnh.", "considered"], ["S + blame + someone + for + noun", "Don't blame me for your mistakes.", "Đừng đổ lỗi cho tôi vì lỗi của bạn.", "blame"], ["S + shift(s) responsibility to + someone", "He always shifts responsibility to his team.", "Anh ta luôn đẩy trách nhiệm cho nhóm.", "shift responsibility|shifts responsibility"], ["What about + noun?", "What about the children?", "Còn bọn trẻ thì sao?", "what about"], ["It is not A who + V, ...", "It is not the teacher who failed the test.", "Không phải giáo viên là người trượt bài kiểm tra.", "it is not|it's not"], ["Isn't / Aren't + S + adj/noun?", "Isn't she the best singer?", "Chẳng phải cô ấy là ca sĩ hay nhất sao?", "isn't|aren't"], ["S + be + vilified / celebrated as + noun", "He was celebrated as a hero.", "Ông ấy được tôn vinh là anh hùng.", "celebrated as|vilified as"], ["S + encourage(d) + someone + to + V", "My parents encouraged me to travel.", "Bố mẹ khuyến khích tôi đi du lịch.", "encouraged|encourage"], ["... as + adj + today as it was + time", "This song is as popular today as it was in 1990.", "Bài hát này ngày nay vẫn nổi tiếng như năm 1990.", "as important|as popular|as it was"]]$j$::jsonb
)
