  $j$[]$j$::jsonb,
  $j$[["lifestyle", "/ˈlaɪfstaɪl/", "lối sống"], ["contributing factor", "/kənˈtrɪbjuːtɪŋ ˈfæktə/", "yếu tố góp phần"], ["typified by", "/ˈtɪpɪfaɪd baɪ/", "tiêu biểu là"], ["diabetes", "/ˌdaɪəˈbiːtiːz/", "bệnh tiểu đường"], ["high blood pressure", "/haɪ blʌd ˈpreʃə/", "cao huyết áp"], ["obesity", "/əʊˈbiːsəti/", "béo phì"], ["surplus", "/ˈsɜːpləs/", "thừa, dư"], ["low-calorie", "/ˌləʊ ˈkæləri/", "ít calo"], ["overweight", "/ˌəʊvəˈweɪt/", "thừa cân"], ["serving", "/ˈsɜːvɪŋ/", "suất ăn, khẩu phần"], ["struggle to", "/ˈstrʌɡl tuː/", "vật lộn để"], ["excess", "/ɪkˈses/", "thừa, quá mức"], ["commercial", "/kəˈmɜːʃl/", "quảng cáo (TV)"], ["be supposed to", "/bi səˈpəʊzd tuː/", "được cho là"], ["reduce", "/rɪˈdjuːs/", "giảm"], ["portion size", "/ˈpɔːʃn saɪz/", "khẩu phần"], ["will", "/wɪl/", "ý chí"], ["keep away from", "/kiːp əˈweɪ frɒm/", "tránh xa"], ["toxic", "/ˈtɒksɪk/", "độc hại"], ["mental focus", "/ˈmentl ˈfəʊkəs/", "sự tập trung tinh thần"], ["root cause", "/ruːt kɔːz/", "căn nguyên"], ["anxious", "/ˈæŋkʃəs/", "lo âu, bồn chồn"], ["outlet", "/ˈaʊtlet/", "cách giải tỏa"], ["distract", "/dɪˈstrækt/", "làm sao nhãng"], ["inappropriate", "/ˌɪnəˈprəʊpriət/", "không phù hợp"], ["handle", "/ˈhændl/", "xử lý"], ["satisfaction", "/ˌsætɪsˈfækʃn/", "sự hài lòng"], ["exertion", "/ɪɡˈzɜːʃn/", "sự gắng sức"], ["enumerate", "/ɪˈnjuːməreɪt/", "liệt kê"], ["pursuit", "/pəˈsjuːt/", "hoạt động theo đuổi"], ["cultivate", "/ˈkʌltɪveɪt/", "nuôi dưỡng, trau dồi"]]$j$::jsonb,
  $j$[["the major contributing factor to", "yếu tố góp phần chính vào"], ["lifestyle-related diseases", "các bệnh liên quan đến lối sống"], ["losing surplus weight", "giảm số cân thừa"], ["the other day", "hôm trước"], ["for a full hour", "suốt một tiếng"], ["struggling to lose excess weight", "vật lộn để giảm cân thừa"], ["filled with food commercials", "đầy quảng cáo đồ ăn"], ["supposed to help you lose fat", "được cho là giúp bạn giảm mỡ"], ["reducing the amount of food you eat", "giảm lượng thức ăn bạn ăn"], ["an unbelievably strong will", "ý chí mạnh khó tin"], ["keep away from this toxic food environment", "tránh xa môi trường đồ ăn độc hại này"], ["still not enough", "vẫn chưa đủ"], ["shift our mental focus from food", "chuyển sự tập trung khỏi đồ ăn"], ["the true root causes", "căn nguyên thực sự"], ["eat as an outlet for these feelings", "ăn để giải tỏa cảm xúc"], ["distract ourselves from these thoughts", "quên đi những suy nghĩ này"], ["handle the negative ones in a better way", "xử lý những điều tiêu cực tốt hơn"], ["lose weight and gain health", "giảm cân và có sức khỏe"], ["the satisfaction of finishing a really fat book", "niềm vui khi đọc xong một cuốn sách dày"], ["The point is", "Vấn đề là"], ["We don't even have to wait.", "Chúng ta thậm chí không cần chờ."]]$j$::jsonb,
  $j$[["The major contributing factor to + noun + is + noun", "The major contributing factor to stress is work.", "Yếu tố chính gây căng thẳng là công việc.", "contributing factor"], ["When I was V-ing ..., I + V-ed ...", "When I was cooking, the phone rang.", "Khi tôi đang nấu ăn thì điện thoại reo.", "when i was"], ["S + let + someone + V", "My mom let me stay up late.", "Mẹ cho tôi thức khuya.", "let"], ["S + be + struggling to + V", "Many students are struggling to find jobs.", "Nhiều sinh viên đang vật lộn tìm việc.", "struggling to"], ["S + be + filled with + noun", "The room was filled with flowers.", "Căn phòng đầy hoa.", "filled with"], ["S + be + supposed to + V", "This tea is supposed to help you sleep.", "Loại trà này được cho là giúp bạn ngủ ngon.", "supposed to"], ["The best way to + V + is not by V-ing, but by V-ing", "The best way to learn is not by reading, but by doing.", "Cách học tốt nhất không phải là đọc, mà là làm.", "best way"], ["It's (really) difficult to + V + unless + clause", "It's difficult to wake up early unless you go to bed early.", "Rất khó dậy sớm trừ khi bạn đi ngủ sớm.", "unless"], ["It is very important to + V", "It is very important to drink enough water.", "Uống đủ nước là rất quan trọng.", "important to"], ["What is most important is to + V", "What is most important is to stay calm.", "Điều quan trọng nhất là giữ bình tĩnh.", "most important"], ["Perhaps instead of V-ing, we should + V", "Perhaps instead of driving, we should walk.", "Có lẽ thay vì lái xe, chúng ta nên đi bộ.", "instead of"], ["S + may + V + as a way to + V", "Some people shop as a way to relax.", "Một số người mua sắm như một cách để thư giãn.", "as a way to"], ["It is A that is + noun", "It is your attitude that is the problem.", "Chính thái độ của bạn mới là vấn đề.", "it is"], ["The point is, + clause", "The point is, we need to start now.", "Vấn đề là chúng ta cần bắt đầu ngay.", "the point is"]]$j$::jsonb
