  $j$[["universal", "/ˌjuːnɪˈvɜːsl/", "chung, phổ quát"], ["journey", "/ˈdʒɜːni/", "hành trình"], ["incurable", "/ɪnˈkjʊərəbl/", "không thể chữa"], ["tenuous", "/ˈtenjuəs/", "bấp bênh, mong manh"], ["fragile", "/ˈfrædʒaɪl/", "mong manh"], ["unpredictable", "/ˌʌnprɪˈdɪktəbl/", "khó đoán"], ["tumultuous", "/tjuːˈmʌltʃuəs/", "đầy sóng gió"], ["subject to", "/ˈsʌbdʒɪkt tuː/", "có thể bị, dễ bị"], ["fatigue", "/fəˈtiːɡ/", "sự mệt mỏi"], ["have a handle on", "/hæv ə ˈhændl ɒn/", "kiểm soát được"], ["in an instant", "/ɪn ən ˈɪnstənt/", "trong chớp mắt"], ["intellectually", "/ˌɪntəˈlektʃuəli/", "về mặt lý trí"], ["impermanent", "/ɪmˈpɜːmənənt/", "vô thường"], ["instinctively", "/ɪnˈstɪŋktɪvli/", "theo bản năng"], ["persist in", "/pəˈsɪst ɪn/", "cố chấp, kiên trì"], ["manipulate", "/məˈnɪpjuleɪt/", "điều khiển, thao túng"], ["external", "/ɪkˈstɜːnl/", "bên ngoài"], ["catastrophic", "/ˌkætəˈstrɒfɪk/", "thảm khốc"], ["security", "/sɪˈkjʊərəti/", "sự an toàn"], ["conceivably", "/kənˈsiːvəbli/", "có thể hình dung được"], ["in the blink of an eye", "/ɪn ðə blɪŋk ɒv ən aɪ/", "trong nháy mắt"], ["internally", "/ɪnˈtɜːnəli/", "bên trong"], ["adaptability", "/əˌdæptəˈbɪləti/", "khả năng thích nghi"], ["self-reliance", "/ˌself rɪˈlaɪəns/", "sự tự lực"], ["overcome", "/ˌəʊvəˈkʌm/", "vượt qua"], ["independent of", "/ˌɪndɪˈpendənt ɒv/", "không phụ thuộc vào"], ["imply", "/ɪmˈplaɪ/", "ngụ ý"], ["capacity", "/kəˈpæsəti/", "khả năng"], ["spiritual", "/ˈspɪrɪtʃuəl/", "thuộc tâm linh"], ["mythologist", "/mɪˈθɒlədʒɪst/", "nhà thần thoại học"], ["common thread", "/ˈkɒmən θred/", "điểm chung xuyên suốt"], ["symbolic of", "/sɪmˈbɒlɪk ɒv/", "tượng trưng cho"], ["wisdom", "/ˈwɪzdəm/", "trí tuệ"]]$j$::jsonb,
  $j$[["an incurable kind of cancer", "loại ung thư không thể chữa"], ["seemingly healthy", "có vẻ khỏe mạnh"], ["subject to disease, fatigue and aging", "có thể bệnh tật, mệt mỏi và già đi"], ["However much we think we have a handle on it", "dù ta nghĩ mình kiểm soát được nó đến đâu"], ["we never really know what's to come", "ta không bao giờ biết điều gì sắp đến"], ["Everything can change in an instant.", "Mọi thứ có thể thay đổi trong chớp mắt."], ["a tough truth to accept", "một sự thật khó chấp nhận"], ["We persist in our attempts to control life.", "Ta cố chấp tìm cách kiểm soát cuộc sống."], ["this is not really the case", "thực ra không phải vậy"], ["mostly wasted energy", "phần lớn là phí sức"], ["Our best-laid plans", "Những kế hoạch chu đáo nhất"], ["in the blink of an eye", "trong nháy mắt"], ["Trust yourself to react appropriately", "Hãy tin mình sẽ phản ứng đúng đắn"], ["Rather than obsess over external events", "Thay vì ám ảnh về sự việc bên ngoài"], ["The more we do this, the more confident we grow", "Càng làm vậy, ta càng tự tin hơn"], ["completely independent of external circumstances", "hoàn toàn không phụ thuộc hoàn cảnh bên ngoài"], ["seek out new experiences", "tìm kiếm trải nghiệm mới"], ["the common thread running through", "sợi chỉ chung xuyên suốt"], ["the inner journey we must all make", "hành trình nội tâm ai cũng phải đi qua"]]$j$::jsonb,
  $j$[["However much + S + V, + clause", "However much I eat, I'm still hungry.", "Dù ăn bao nhiêu tôi vẫn đói.", "however much"], ["S + be + a tough + noun + to + V", "It's a tough decision to make.", "Đó là một quyết định khó đưa ra.", "tough"], ["..., for though + clause, + clause", "I stayed, for though I was tired, I wanted to help.", "Tôi ở lại, vì dù mệt tôi vẫn muốn giúp.", "though"], ["S + persist(s) in + V-ing / noun", "He persists in calling me late at night.", "Anh ta cứ khăng khăng gọi tôi lúc đêm khuya.", "persist in"], ["S + be + subject to + noun", "Prices are subject to change.", "Giá có thể thay đổi.", "subject to"], ["There is no + noun + to be found in + place", "There is no peace to be found in the city.", "Ở thành phố chẳng tìm được sự yên bình.", "to be found"], ["Where, then, is + noun + to be found?", "Where, then, is happiness to be found?", "Vậy hạnh phúc nằm ở đâu?", "where, then|where then"], ["Not A, but rather B", "The problem is not money, but rather time.", "Vấn đề không phải tiền mà là thời gian.", "but rather"], ["Rather than + V, S + V", "Rather than complain, try to fix it.", "Thay vì phàn nàn, hãy thử sửa nó.", "rather than"], ["The more + S + V, the more + adj + S + V", "The more you practice, the better you get.", "Càng luyện tập, bạn càng giỏi.", "the more"], ["S + be + independent of + noun", "Her income is independent of her husband's.", "Thu nhập của cô ấy không phụ thuộc vào chồng.", "independent of"], ["This implies that + clause", "This implies that we need more time.", "Điều này ngụ ý rằng chúng ta cần thêm thời gian.", "implies"], ["I think of + A + as + B", "I think of him as my brother.", "Tôi coi anh ấy như anh trai.", "think of|as"], ["S + be + symbolic of + noun", "The dove is symbolic of peace.", "Chim bồ câu tượng trưng cho hòa bình.", "symbolic of"]]$j$::jsonb
)
