  $j$[[8.3, "Man Injured at Fast Food Restaurant", "Người đàn ông bị thương ở nhà hàng thức ăn nhanh"], [18.3, "There is a man. He is 79 years old.", "Có một người đàn ông. Ông 79 tuổi."], [27.3, "He is hurt while waiting in his brand new car.", "Ông bị thương trong lúc đang chờ trong chiếc xe mới tinh của mình."], [35.0, "He is in a drive-through at a fast food restaurant.", "Ông đang ở làn mua hàng qua xe của một nhà hàng thức ăn nhanh."], [44.6, "The man gets a mild burn when, all of a sudden, an employee spills coffee on him.", "Ông bị bỏng nhẹ khi bỗng nhiên một nhân viên làm đổ cà phê lên người ông."], [57.8, "The man says, \"Ow! This coffee is really hot!\"", "Ông kêu lên: \"Á! Cà phê này nóng quá!\""], [67.7, "The restaurant manager feels very bad.", "Quản lý nhà hàng cảm thấy rất áy náy."], [72.1, "Before the man drives off, the manager gives him a free gallon of coffee and a free sandwich.", "Trước khi ông lái xe đi, người quản lý tặng ông một gallon cà phê và một chiếc bánh sandwich miễn phí."], [88.8, "The employee who spilled the coffee is a new hire.", "Nhân viên làm đổ cà phê là người mới vào làm."], [96.9, "She is let go for her mistake.", "Cô ấy bị cho nghỉ việc vì lỗi đó."]]$j$::jsonb,
