  $j$[["lives on a farm", "sống ở một trang trại"], ["once owned them", "từng là chủ của chúng"], ["It lasts seven days", "Nó kéo dài bảy ngày"], ["turns into a big river", "biến thành một dòng sông lớn"], ["moves her cows to higher ground", "lùa đàn bò lên chỗ cao hơn"], ["slips and hits her head", "trượt chân và đập đầu"], ["knocks her out for a moment or two", "làm cô bất tỉnh một lúc"], ["When she comes to", "Khi cô tỉnh lại"], ["The water is now waist-high", "Giờ nước đã cao ngang thắt lưng"], ["throws her arm around his neck and hangs on", "quàng tay qua cổ nó và bám chặt"], ["pulls Buffy out of the water", "kéo Buffy ra khỏi nước"], ["it rains very hard", "trời mưa rất to"], ["I owe my life to him", "Tôi nợ nó cả mạng sống"]]$j$::jsonb,
