insert into public.effortless_lessons (course, lesson_no, slug, title, level, description, cover, main_audio, vocab_audio, ms_audio, pov_audio, com_audio, main_story, mini_story, ms_parts, pov_story, com_story, vocab, phrases, patterns)
values (
  'Flow English',
  15,
  'lemon-dog-2',
  'Lemon Dog 2',
  'elementary',
  'Phần 2: Chó Chanh đi siêu thị mua 36.001 quả chanh, hóa đơn lên tới 53 triệu đô — may mà cô thu ngân đã "phải lòng" chú. Học cách nói khi đi mua sắm, thanh toán, thiếu tiền và tán tỉnh — kèm lời bình.',
  'https://images.unsplash.com/photo-1789925941661-ce19d97b1c87',
  'Flow_English_Lesson/214a Lemon Dog 2 (main).mp3',
  null,
  'Flow_English_Lesson/214c Lemon Dog 2 (ms).mp3',
