[2076.7, "q", "Did he buy 49 kilos?"], [2080.7, "a", "No, not kilos, pounds."], [2084.5, "s", "He bought forty-nine pounds of garlic."], [2088.6, "q", "Did he eat forty-nine pounds or forty-nine kilos?"], [2094.2, "a", "He ate forty-nine pounds."], [2099.1, "q", "Who ate forty-nine pounds of garlic?"], [2106.4, "a", "Will Smith ate forty-nine pounds of garlic."], [2110.6, "q", "Why?"], [2114.7, "a", "Well, because he wanted to kill the mosquitoes."], [2122.1, "s", "He ate 49 pounds of garlic because he wanted to kill the mosquitoes."], [2132.4, "s", "So Will bought a huge bag of garlic at the grocery store."], [2137.2, "s", "He ate 49 pounds of garlic."], [2140.5, "s", "Then he went to sleep."], [2145.8, "s", "Did he go to the store No, he didn't go to the store."], [2154.4, "s", "He went to sleep."], [2159.0, "q", "Did he start to sleep?"], [2165.4, "a", "Yes, he went to sleep."], [2168.6, "q", "What did he do?"], [2171.7, "a", "He went to sleep."], [2173.7, "q", "Who went to sleep?"], [2177.2, "a", "Will Smith."], [2179.5, "q", "Did David Beckham go to sleep?"], [2183.5, "a", "No, David Beckham didn't go to sleep."], [2186.1, "s", "Will Smith went to sleep."], [2190.4, "s", "During the night, thousands of mosquitoes bit him."], [2197.8, "q", "How many mosquitoes bit him?"], [2203.7, "a", "No."], [2211.5, "s", "Thousands of mosquitoes bit him."], [2215.8, "q", "Thousands of cats bit him?"], [2218.7, "a", "No, not cats, thousands of cats didn't bite him."], [2223.4, "s", "Thousands of mosquitoes bit him."], [2228.3, "s", "How many mosquitoes bit him?"], [2233.4, "q", "When did they bite him?"], [2239.0, "a", "During the night."], [2241.9, "q", "Did they bite him during the day or during the night?"], [2248.4, "a", "Well, during the night."], [2250.0, "s", "Mosquitoes bite during the night."], [2253.2, "s", "The mosquitoes bit him during the night."], [2259.6, "q", "What bit him during the night?"], [2265.2, "a", "Mosquitoes."], [2265.8, "s", "Mosquitoes bit him during the night."], [2271.1, "q", "Did they bite him during the day?"], [2275.2, "a", "No."], [2276.8, "q", "Who did they bite?"], [2280.2, "a", "They bit Will Smith."], [2282.9, "q", "And when did they bite him?"], [2287.4, "a", "They bit him during the night."], [2290.9, "s", "But, they all died because of the garlic."], [2298.9, "q", "Why did they die?"], [2302.9, "a", "Because of the garlic."], [2306.0, "s", "Because he had eaten garlic."], [2311.0, "q", "Who had eaten garlic?"], [2315.7, "a", "Will Smith had eaten garlic."], [2319.9, "q", "When did he eat garlic?"], [2322.3, "a", "Well, before he went to sleep."], [2329.0, "s", "He had eaten garlic before he went to sleep, so all the mosquitoes died."], [2340.5, "q", "What died?"], [2344.1, "a", "Well, all the mosquitoes died."], [2348.0, "q", "When did Will eat garlic?"], [2351.3, "a", "He ate garlic before he went to sleep."], [2361.4, "s", "When Will woke up, there were thousands of dead mosquitoes on the bed."], [2370.8, "q", "What was on the bed?"], [2376.2, "a", "Thousands of dead mosquitoes."], [2381.1, "q", "Were thousands of dead ducks on the bed?"], [2387.9, "a", "No, not ducks."], [2389.0, "s", "Thousands of dead mosquitoes were on the bed."], [2395.9, "q", "Where were the dead mosquitoes on the bed?"], [2403.2, "a", "They were on the bed."], [2407.1, "q", "Were they on the table or were they on the bed?"], [2412.8, "a", "They were on the bed whose bed were the mosquitoes on."], [2423.6, "q", "Will Smith's they were on Will Smith's bed were they on Beckham's bed no they weren't on David Beckham's bed whose bed were they on?"], [2439.8, "a", "They were on Will Smith's bed were the mosquitoes alive or were the mosquitoes dead they."], [2453.9, "s", "Were dead the mosquitoes were dead?"], [2458.5, "q", "How many mosquitoes were dead?"], [2463.9, "a", "Thousands of mosquitoes were dead where were they dead on the bed they were dead on the bed on Will Smith's bed."], [2482.2, "q", "When did Will see the mosquitoes?"], [2491.5, "a", "When he woke up."], [2494.0, "s", "When he woke up, there were thousands of dead mosquitoes on the bed."], [2503.0, "s", "Were there thousands of dead mosquitoes on the bed when he went to sleep."], [2515.5, "s", "No, not when he went to sleep."], [2519.7, "s", "There weren't thousands of dead mosquitoes on the bed when he went to sleep."], [2528.4, "s", "There were thousands of dead mosquitoes on the bed when he woke up."], [2537.9, "q", "Who woke up?"], [2541.0, "a", "Will Smith woke up."], [2543.9, "q", "When did he wake up?"], [2548.2, "a", "Well, he woke up in the morning, of course."], [2552.7, "s", "Will Smith woke up in the morning."], [2558.6, "q", "What was on the bed?"], [2562.9, "a", "Thousands of dead mosquitoes were on the bed."], [2565.9, "s", "When he woke up, he yelled, Chris Moses is a genius!"], [2576.1, "s", "Is Chris Moses intelligent?"], [2579.2, "q", "Or is Chris Moses stupid?"], [2584.4, "a", "He's intelligent."], [2586.4, "q", "Is he very, very intelligent?"], [2590.3, "a", "Yes, he's a genius!"], [2594.5, "q", "Who is a genius?"], [2599.1, "a", "Chris Moses."], [2600.4, "s", "Chris Moses is a genius."], [2604.4, "q", "Is David Beckham a genius?"], [2609.2, "a", "No, unfortunately, David Beckham is stupid, but Chris Moses is a genius."], [2618.2, "s", "Is Einstein a genius?"], [2621.3, "q", "Well, was Einstein a genius?"], [2624.7, "a", "He's dead."], [2627.6, "s", "Well, little bit."], [2629.5, "s", "Einstein was a little bit a genius, but Chris Moses is a super genius."], [2639.6, "s", "Why is Chris Moses a genius?"], [2645.7, "q", "Why is Chris Moses a genius?"], [2650.2, "a", "Because he knows how to kill mosquitoes."], [2659.1, "q", "Who at Chris Moses was a genius?"], [2669.1, "a", "Will Smith."], [2670.4, "s", "Will Smith thought that Chris Moses was a genius."], [2677.1, "s", "Will Smith was very happy because all the mosquitoes were dead."], [2686.2, "s", "The end."]]}]$j$::jsonb,
