  $j$[["sweet dreams", "/swiːt driːmz/", "chúc ngủ ngon"], ["couple", "/ˈkʌpl/", "cặp đôi, vợ chồng"], ["bedtime", "/ˈbedtaɪm/", "giờ đi ngủ"], ["married", "/ˈmærid/", "đã kết hôn"], ["husband", "/ˈhʌzbənd/", "chồng"], ["retire for the night", "/rɪˈtaɪə fə ðə naɪt/", "đi ngủ (trang trọng)"], ["any time", "/ˈeni taɪm/", "bất cứ lúc nào"], ["ready for bed", "/ˈredi fə bed/", "sẵn sàng đi ngủ"], ["upset", "/ʌpˈset/", "bực bội, phật ý"], ["get into bed", "/ɡet ˈɪntə bed/", "lên giường"], ["according to", "/əˈkɔːdɪŋ tə/", "theo (ý kiến của)"], ["period", "/ˈpɪəriəd/", "thế thôi, chấm hết"], ["timetable", "/ˈtaɪmteɪbl/", "lịch, thời gian biểu"], ["needless to say", "/ˈniːdləs tə seɪ/", "khỏi phải nói"], ["figure out", "/ˈfɪɡər aʊt/", "tìm ra cách giải quyết"], ["without", "/wɪˈðaʊt/", "mà không"], ["resent", "/rɪˈzent/", "oán giận, bực tức"], ["each other", "/iːtʃ ˈʌðə(r)/", "nhau"], ["signed", "/saɪnd/", "ký tên"], ["be tired of", "/bi ˈtaɪəd əv/", "chán, mệt mỏi vì"]]$j$::jsonb,
  $j$[["Dear Dr. Ellis", "Kính gửi Tiến sĩ Ellis"], ["when it's time for us to retire for the night", "khi nào là lúc chúng tôi đi ngủ"], ["any time from 9:30 to 11:30", "bất cứ lúc nào từ 9 giờ 30 đến 11 giờ 30"], ["I'm ready for bed", "tôi sẵn sàng đi ngủ"], ["he gets upset", "anh ấy bực mình"], ["finish a book I'm reading", "đọc nốt cuốn sách đang đọc"], ["According to him, ...", "Theo anh ấy, ..."], ["..., period.", "..., thế thôi."], ["It's always on his timetable", "Lúc nào cũng theo lịch của anh ấy"], ["Needless to say, ...", "Khỏi phải nói, ..."], ["we have gone to bed angry many times", "chúng tôi nhiều lần đi ngủ trong giận dỗi"], ["How do we figure it out?", "Làm sao chúng tôi giải quyết chuyện này?"], ["Tired of Being Tired", "Mệt mỏi vì mệt mỏi"]]$j$::jsonb,
  $j$[["S + tells + me + when it's time for + someone + to + V", "My mom tells me when it's time for me to go home.", "Mẹ bảo tôi khi nào đến giờ phải về nhà.", "time for"], ["This can be any time from + time + to + time", "The delivery can be any time from 8 to 12.", "Giao hàng có thể vào bất cứ lúc nào từ 8 đến 12 giờ.", "any time"], ["If + S + V, S + gets + adj", "If I don't eat breakfast, I get hungry at 10.", "Nếu không ăn sáng, tôi sẽ đói lúc 10 giờ.", "gets"], ["According to + someone, + clause", "According to the doctor, I need more sleep.", "Theo bác sĩ, tôi cần ngủ nhiều hơn.", "According to"], ["Needless to say, + clause", "It rained all day. Needless to say, we stayed home.", "Trời mưa cả ngày. Khỏi phải nói, chúng tôi ở nhà.", "Needless to say"], ["S + have/has + V3 + many times", "I have visited Da Lat many times.", "Tôi đã đến Đà Lạt nhiều lần.", "many times"], ["How do we + V + without + V-ing?", "How do we save money without giving up coffee?", "Làm sao tiết kiệm tiền mà không phải bỏ cà phê?", "without"], ["S + is tired of + V-ing", "I'm tired of waiting.", "Tôi chán phải chờ rồi.", "tired of"]]$j$::jsonb
)
